import json
from pathlib import Path
# search all old-mac transcripts for file content of daily-report-wake.sh
root=Path('/Users/mac/.dc-platform/memory/mirrors/agent-transcripts/old-mac')
hits=0
for p in root.rglob('*.jsonl'):
  for line in p.open(encoding='utf-8', errors='ignore'):
    if 'AGENT_LOOP_WAKE_DAILY_REPORT' in line and 'wake_feed' in line and '#!/' in line:
      o=json.loads(line)
      role=o.get('role')
      # tool results might be in user role in some formats - check content
      content=o.get('message',{}).get('content')
      if not content:
        continue
      texts=[]
      if isinstance(content,str):
        texts=[content]
      elif isinstance(content,list):
        for c in content:
          if isinstance(c,dict):
            if c.get('type')=='text': texts.append(c.get('text',''))
            # tool_result
            if 'content' in c and isinstance(c['content'],str): texts.append(c['content'])
      for t in texts:
        if 'AGENT_LOOP_WAKE_DAILY_REPORT' in t and len(t)>200:
          print('FILE', p.name, 'role', role, 'len', len(t))
          # find shebang region
          idx=t.find('#!/')
          if idx>=0:
            print(t[idx:idx+2500])
          else:
            print(t[:2000])
          print('=====')
          hits+=1
          if hits>=3: raise SystemExit
print('hits', hits)
